#!/usr/bin/env node
// Captures the yt-dlp fixtures in tests/fixtures/ytdlp/ from a real yt-dlp run
// against a local HTTP server (STATE.md F0.6, SPEC §25.2). Nothing leaves the
// machine: every URL points at 127.0.0.1 and the media is generated by ffmpeg.
//
//   VV_YTDLP=/path/to/yt-dlp node scripts/capture-ytdlp-fixtures.mjs
//
// Needs: yt-dlp at the version pinned in args.json, ffmpeg on PATH.
// Optional: VV_CAPTURE_TINY_DIR=<a very small writable mount> adds the real
// "disk full" run (on Linux: `mount -t tmpfs -o size=24k tmpfs <dir>` as root).
//
// This is a developer tool, not part of `npm run verify`: the tests read the
// committed output and never run yt-dlp.

import { spawn, spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync, createReadStream, statSync } from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = join(root, "tests", "fixtures", "ytdlp");
const args = JSON.parse(readFileSync(join(outDir, "args.json"), "utf8"));
const ytdlp = process.env.VV_YTDLP ?? "yt-dlp";
const FIXED_ORIGIN = "http://127.0.0.1:8765";

const version = spawnSync(ytdlp, ["--version"], { encoding: "utf8" }).stdout?.trim();
if (version !== args.ytDlpVersion) {
  console.error(`yt-dlp ${version ?? "not found"} does not match pinned ${args.ytDlpVersion} (args.json)`);
  process.exit(1);
}
const ffmpegVersion = spawnSync("ffmpeg", ["-version"], { encoding: "utf8" }).stdout?.split("\n")[0];
if (!ffmpegVersion) {
  console.error("ffmpeg not found on PATH");
  process.exit(1);
}

// --- media -----------------------------------------------------------------
const work = mkdtempSync(join(tmpdir(), "vv-ytdlp-capture-"));
const www = join(work, "www");
mkdirSync(www);
const ff = (argv) => {
  const r = spawnSync("ffmpeg", ["-loglevel", "error", "-y", ...argv], { cwd: www, stdio: "inherit" });
  if (r.status !== 0) throw new Error(`ffmpeg failed: ${argv.join(" ")}`);
};
const src = (w, h, t) => ["-f", "lavfi", "-i", `testsrc=size=${w}x${h}:rate=25`, "-f", "lavfi", "-i", "sine=frequency=440", "-t", String(t)];
const h264 = ["-c:v", "libx264", "-g", "50", "-keyint_min", "50", "-sc_threshold", "0", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest"];
ff([...src(320, 240, 4), ...h264, "clip.mp4"]);
for (const [w, h] of [[320, 240], [640, 480]]) {
  ff([...src(w, h, 6), ...h264, "-f", "hls", "-hls_time", "2", "-hls_playlist_type", "vod", "-hls_segment_filename", `v${h}_%03d.ts`, `v${h}.m3u8`]);
}
writeFileSync(join(www, "master.m3u8"), [
  "#EXTM3U",
  '#EXT-X-STREAM-INF:BANDWIDTH=300000,RESOLUTION=320x240,CODECS="avc1.64000d,mp4a.40.2"',
  "v240.m3u8",
  '#EXT-X-STREAM-INF:BANDWIDTH=800000,RESOLUTION=640x480,CODECS="avc1.64001e,mp4a.40.2"',
  "v480.m3u8",
  "",
].join("\n"));
// Same variant, but every segment answers 403: the media URL stopped working
// after extraction succeeded (download-phase failure).
writeFileSync(join(www, "expired.m3u8"), readFileSync(join(www, "v240.m3u8"), "utf8").replace(/^v240_/gm, "denied/v240_"));
writeFileSync(join(www, "two-videos.html"), [
  "<!doctype html><title>Two clips</title>",
  '<video src="clip.mp4"></video>',
  '<video src="v240.m3u8"></video>',
  "",
].join("\n"));

// --- server ----------------------------------------------------------------
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const server = createServer(async (req, res) => {
  const path = decodeURIComponent(new URL(req.url, "http://x").pathname);
  if (path === "/forbidden.mp4" || path.startsWith("/denied/")) return void res.writeHead(403).end("Forbidden");
  if (path === "/ratelimited.mp4") return void res.writeHead(429, { "Retry-After": "120" }).end("Too Many Requests");
  if (path === "/slow.mp4" || path === "/nolength.mp4") {
    const data = readFileSync(join(www, "clip.mp4"));
    const headers = { "Content-Type": "video/mp4" };
    if (path === "/slow.mp4") headers["Content-Length"] = String(data.length);
    res.writeHead(200, headers);
    for (let i = 0; i < data.length && !res.destroyed; i += 8192) {
      res.write(data.subarray(i, i + 8192));
      await sleep(150);
    }
    return void res.end();
  }
  if (path === "/") return void res.writeHead(200, { "Content-Type": "text/html" }).end("<!doctype html><title>No media here</title><p>Nothing to extract.</p>");
  const file = join(www, path.replace(/^\/+/, ""));
  if (!file.startsWith(www) || !statSync(file, { throwIfNoEntry: false })?.isFile()) return void res.writeHead(404).end("File not found");
  const type = file.endsWith(".m3u8") ? "application/vnd.apple.mpegurl" : file.endsWith(".html") ? "text/html" : file.endsWith(".ts") ? "video/mp2t" : "video/mp4";
  res.writeHead(200, { "Content-Type": type, "Content-Length": String(statSync(file).size) });
  createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const origin = `http://127.0.0.1:${server.address().port}`;
const deadPort = await new Promise((r) => {
  const s = createServer().listen(0, "127.0.0.1", () => {
    const p = s.address().port;
    s.close(() => r(p));
  });
});

// --- runs ------------------------------------------------------------------
function normalize(text) {
  return text.split(origin).join(FIXED_ORIGIN).split(`127.0.0.1:${deadPort}`).join("127.0.0.1:9").split(work).join("<WORK>");
}

/** Runs yt-dlp; `stopAfter` sends `signal` once that many progress lines arrived. */
function run(argv, { stopAfter, signal } = {}) {
  return new Promise((resolve) => {
    const child = spawn(ytdlp, argv, { cwd: work, env: { ...process.env, NO_COLOR: "1" } });
    let stdout = "";
    let stderr = "";
    let progress = 0;
    child.stdout.on("data", (b) => {
      stdout += b;
      progress += (b.toString().match(/^vv-progress /gm) ?? []).length;
      if (stopAfter && progress >= stopAfter && !child.killed) child.kill(signal);
    });
    child.stderr.on("data", (b) => (stderr += b));
    child.on("close", (code, sig) => resolve({ exitCode: code, signal: sig, stdout: normalize(stdout), stderr: normalize(stderr) }));
  });
}

const dl = (name) => ["-P", join(work, "dl", name), "-o", "%(id)s.%(ext)s"];
const meta = (url) => [...args.common, ...args.metadata, url];
const down = (name, url, extra = []) => [...args.common, ...args.download, ...dl(name), ...extra, url];

const scenarios = [
  { name: "metadata-hls", kind: "metadata", argv: meta(`${origin}/master.m3u8`) },
  { name: "metadata-direct", kind: "metadata", argv: meta(`${origin}/clip.mp4`) },
  { name: "metadata-playlist", kind: "metadata", argv: meta(`${origin}/two-videos.html`) },
  { name: "download-direct", kind: "download", argv: down("direct", `${origin}/slow.mp4`) },
  { name: "download-unknown-total", kind: "download", argv: down("nolength", `${origin}/nolength.mp4`) },
  { name: "download-hls", kind: "download", argv: down("hls", `${origin}/master.m3u8`, ["-f", "800"]) },
  { name: "cancel-sigint", kind: "download", argv: down("sigint", `${origin}/slow.mp4`), stopAfter: 3, signal: "SIGINT" },
  { name: "cancel-killed", kind: "download", argv: down("killed", `${origin}/slow.mp4`), stopAfter: 3, signal: "SIGKILL" },
  { name: "error-not-found", kind: "metadata", argv: meta(`${origin}/missing.mp4`) },
  { name: "error-forbidden", kind: "metadata", argv: meta(`${origin}/forbidden.mp4`) },
  { name: "error-rate-limited", kind: "metadata", argv: meta(`${origin}/ratelimited.mp4`) },
  { name: "error-connection-refused", kind: "metadata", argv: meta(`http://127.0.0.1:${deadPort}/clip.mp4`) },
  { name: "error-unsupported", kind: "metadata", argv: meta(`${origin}/`) },
  { name: "error-fragments-forbidden", kind: "download", argv: down("expired", `${origin}/expired.m3u8`) },
];
if (process.env.VV_CAPTURE_TINY_DIR) {
  const tiny = process.env.VV_CAPTURE_TINY_DIR;
  scenarios.push({
    name: "error-disk-full",
    kind: "download",
    argv: [...args.common, ...args.download, "-P", tiny, "-o", "%(id)s.%(ext)s", `${origin}/clip.mp4`],
    pathAlias: [tiny, "<TINY>"],
  });
}

rmSync(join(outDir, "runs"), { recursive: true, force: true });
mkdirSync(join(outDir, "runs"), { recursive: true });
const manifest = {
  _comment: "Written by scripts/capture-ytdlp-fixtures.mjs. Real yt-dlp output against a local server; do not edit by hand.",
  ytDlpVersion: version,
  ffmpeg: ffmpegVersion,
  capturedOn: process.platform,
  capturedAt: new Date().toISOString().slice(0, 10),
  runs: [],
};
for (const s of scenarios) {
  const r = await run(s.argv, s);
  if (s.pathAlias) {
    r.stdout = r.stdout.split(s.pathAlias[0]).join(s.pathAlias[1]);
    r.stderr = r.stderr.split(s.pathAlias[0]).join(s.pathAlias[1]);
  }
  const file = `runs/${s.name}.json`;
  const body = { name: s.name, kind: s.kind, exitCode: r.exitCode, signal: r.signal, stdout: r.stdout, stderr: r.stderr };
  writeFileSync(join(outDir, file), JSON.stringify(body, null, 2) + "\n");
  manifest.runs.push({ name: s.name, kind: s.kind, file, exitCode: r.exitCode, signal: r.signal });
  console.log(`${s.name}: exit ${r.exitCode ?? "-"}${r.signal ? ` (${r.signal})` : ""}`);
}
writeFileSync(join(outDir, "capture-manifest.json"), JSON.stringify(manifest, null, 2) + "\n");

server.close();
rmSync(work, { recursive: true, force: true });
console.log(`wrote ${manifest.runs.length} runs to ${outDir}`);
